PROCEDURE @@proc@@ IS
    l_count PLS_INTEGER := 0;
BEGIN
    FOR rec IN (SELECT @@col@@ FROM @@tab@@ ORDER BY @@col@@) LOOP
        @@proc2@@(rec.@@col@@);
        l_count := l_count + 1;
        IF MOD(l_count, @@num@@) = 0 THEN
            COMMIT; -- @expect
        END IF;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_outer IN PLS_INTEGER, p_inner IN PLS_INTEGER) IS
BEGIN
    FOR i IN 1 .. p_outer LOOP
        @@proc2@@(i, 0);
        FOR j IN 1 .. p_inner LOOP
            @@proc2@@(i, j);
            COMMIT; -- @expect
        END LOOP;
    END LOOP;
    DBMS_OUTPUT.PUT_LINE('batches done');
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_failed PLS_INTEGER := 0;
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        BEGIN
            @@proc2@@(p_ids(i));
        EXCEPTION
            WHEN VALUE_ERROR THEN
                ROLLBACK; -- @expect
                l_failed := l_failed + 1;
        END;
    END LOOP;
    DBMS_OUTPUT.PUT_LINE('failed: ' || l_failed);
END @@proc@@;

PROCEDURE @@proc@@ (p_limit IN NUMBER) IS
    l_n NUMBER := 0;
BEGIN
    WHILE l_n < p_limit LOOP
        @@proc2@@(l_n);
        l_n := l_n + 1;
        COMMIT WORK; -- @expect
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
BEGIN
    FOR i IN 1 .. p_n LOOP
        CASE MOD(i, 3)
            WHEN 0 THEN
                COMMIT; -- @expect
            WHEN 1 THEN
                @@proc2@@(i);
            ELSE
                NULL;
        END CASE;
    END LOOP;
END @@proc@@;

