PROCEDURE @@proc@@ (p_groups IN PLS_INTEGER) IS
BEGIN
    FOR g IN 1 .. p_groups LOOP
        FOR rec IN (SELECT @@col@@ FROM @@tab@@ WHERE grp = g) LOOP
            @@proc2@@(rec.@@col@@);
        END LOOP;
    END LOOP;
    COMMIT;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        SAVEPOINT sp_row;
        BEGIN
            @@proc2@@(p_ids(i));
        EXCEPTION
            WHEN DUP_VAL_ON_INDEX THEN
                ROLLBACK TO SAVEPOINT sp_row;
        END;
    END LOOP;
    COMMIT;
END @@proc@@;

PROCEDURE @@proc@@ (p_steps IN PLS_INTEGER) IS
    l_total PLS_INTEGER := 0;
BEGIN
    FOR i IN 1 .. p_steps LOOP
        log_pkg.info('COMMIT');
        @@proc2@@(i);
        l_total := l_total + i;
    END LOOP;
    log_pkg.info('total=' || l_total);
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_i PLS_INTEGER := 1;
BEGIN
    WHILE l_i <= p_ids.COUNT LOOP
        @@proc2@@(p_ids(l_i));
        l_i := l_i + 1;
    END LOOP;
    COMMIT;
    @@proc2@@(0);
END @@proc@@;

PROCEDURE @@proc@@ (p_mode IN VARCHAR2) IS
    l_done BOOLEAN;
BEGIN
    FOR i IN 1 .. 3 LOOP
        @@proc2@@(p_mode, l_done);
    END LOOP;
    IF l_done THEN
        COMMIT;
    ELSE
        ROLLBACK;
    END IF;
END @@proc@@;
